import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv2d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size,
    int in_channels,
    int in_h, int in_w,
    int out_channels,
    int out_h, int out_w,
    int kernel_size,
    int stride,
    int padding)
{
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * out_channels * out_h * out_w;
    if (idx >= total) return;

    int ow = idx % out_w;
    int oh = (idx / out_w) % out_h;
    int oc = (idx / (out_w * out_h)) % out_channels;
    int n  = idx / (out_w * out_h * out_channels);

    float sum = bias[oc];

    int in_h_start = oh * stride - padding;
    int in_w_start = ow * stride - padding;

    for (int ic = 0; ic < in_channels; ++ic) {
        const float* input_ptr = input + ((n * in_channels + ic) * in_h) * in_w;
        const float* weight_ptr = weight + ((oc * in_channels + ic) * kernel_size) * kernel_size;

        for (int kh = 0; kh < kernel_size; ++kh) {
            int ih = in_h_start + kh;
            if (ih < 0 || ih >= in_h) continue;
            for (int kw = 0; kw < kernel_size; ++kw) {
                int iw = in_w_start + kw;
                if (iw < 0 || iw >= in_w) continue;
                sum += input_ptr[ih * in_w + iw] * weight_ptr[kh * kernel_size + kw];
            }
        }
    }

    output[idx] = sum;
}

torch::Tensor conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding)
{
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int in_h = input.size(2);
    const int in_w = input.size(3);

    const int out_channels = weight.size(0);
    const int kernel_size = weight.size(2);

    const int out_h = (in_h + 2 * padding - kernel_size) / stride + 1;
    const int out_w = (in_w + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());

    int total = batch_size * out_channels * out_h * out_w;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;

    conv2d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        in_h, in_w,
        out_channels,
        out_h, out_w,
        kernel_size,
        stride,
        padding
    );

    return output;
}
"""

conv2d_cpp_source = r"""
torch::Tensor conv2d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding);
"""

conv2d_module = load_inline(
    name="conv2d_module",
    cpp_sources=conv2d_cpp_source,
    cuda_sources=conv2d_source,
    functions=["conv2d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super(ModelNew, self).__init__()
        self.in_channels = 3
        self.out_channels = 96
        self.kernel_size = 11
        self.stride = 4
        self.padding = 2

        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels, self.kernel_size, self.kernel_size)
        )
        self.bias = nn.Parameter(torch.empty(self.out_channels))

        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)
        fan_in = self.in_channels * self.kernel_size * self.kernel_size
        bound = 1 / (fan_in ** 0.5)
        nn.init.uniform_(self.bias, -bound, bound)

        self.conv2d = conv2d_module

    def forward(self, x):
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()
        bias = self.bias.contiguous().cuda()
        return self.conv2d.conv2d_cuda(x, weight, bias, self.stride, self.padding)

